/**
 * Implementation des Nim-Spiels gegen den Computer
 * @author: Klaus Dingeman
 * @version: 04.03.2018
*/
import sas.*;
import sasio.*;
public class NIM
{
    private View view;
    private Spielfeld spielfeld;
    private Spieler spieler;
    private Computer computer;
    private boolean spielBeendet;
    /**
     * Konstruktor für Objekte der Klasse NIM
     */
    public NIM()
    {
       view = new View(800, 400, "NIM"); 
       spielfeld = new Spielfeld(view);
       spieler = new Spieler(spielfeld);
       computer = new Computer(spielfeld);
       spielBeendet = false;
    }

    public void siegerNachricht(char sieger) {

        String s = "";
        if (sieger=='c') {
            s = "Der Computer hat gewonnen.";
        } else {
            s = "Herzlichen Glückwunsch, du hast gewonnen.";
        }
        Tools.message(s,"Gewinner");
    }

    public void spielen() {
        char sieger = 'c';
        while (!spielBeendet) {
           spieler.spielerZug();
           if (spielfeld.spielBeendet()) {
               spielBeendet = true;
               sieger = 's';
           } else {
               computer.computerZug();
               if (spielfeld.spielBeendet()) {
                   spielBeendet = true;
               } 
             }   
           view.wait(10);
        }
        siegerNachricht(sieger);
    }

    public static void main(String[] args) {
        NIM nim = new NIM();
        nim.spielen();
   }
}

import sas.*;
import sasio.*;
import java.awt.Color;
class Spielfeld {
    private Schale[] schalen = new Schale[5];
    private Textfield[] txtfldEingabe = new Textfield[5];
    private View view;

    public Spielfeld(View pView) {
        view = pView;
        Text titel = new Text(350, 40, "NIM", Color.RED);
        titel.setFontSerif(true, 32);
        for (int i=0; i<5; i++) {
            int nr = i+1;
            new Text(55+i*150, 120, "Schale "+nr, Color.BLACK);
            schalen[i] = new Schale(50+i*150, 150,100, Color.BLACK);
            txtfldEingabe[i] = new Textfield(85+i*150, 270,30,20,"",view);
        }
        new Text(50, 310, "Eingabefeld klicken, Anzahl der Steine eingeben und <Enter> drücken");
        verteileChips();
    }

    public void verteileChips() {
        int schaleNr;
        for (int i = 0; i<40; i++) {
            Circle chip = new Circle(0,0,8,Color.RED);
            do
               schaleNr = Tools.randomNumber(0,4);
            while (schalen[schaleNr].gibAnzahlChips() == 15);
            schalen[schaleNr].inhaltHinzu(chip);
        }
    }


    public void ziehen() {
        boolean zugKorrekt = false;
        int fokus = 0;
        while (!zugKorrekt) {
            for (int i=0; i<5; i++) {
                if (txtfldEingabe[i].clicked()) {
                    txtfldEingabe[fokus].setActivated(false);
                    fokus = i;
                    txtfldEingabe[fokus].setActivated(true);
                }
            }
            if (txtfldEingabe[fokus].enterPressed()) {
                int zug = Integer.parseInt(txtfldEingabe[fokus].getText());
                if (zug > 0 && zug <= schalen[fokus].gibAnzahlChips()) {
                    schalen[fokus].inhaltEntfernen(zug);
                    txtfldEingabe[fokus].deleteText();
                    txtfldEingabe[fokus].setActivated(false);
                    zugKorrekt = true;
                } else {
                    zugKorrekt = false;
                    txtfldEingabe[fokus].setActivated(true);
                    Tools.message("Kein korrekter Zug", "Fehler");
                }
            }
        }
    }

    public boolean spielBeendet(){
        int summe = 0;
        for (int i = 0; i < 5; i++) {
          summe = summe + schalen[i].gibAnzahlChips();     
        }
        return summe == 0;
    }

    public void nimmWeg(int schaleNr, int anzahl) {
        schalen[schaleNr].inhaltEntfernen(anzahl);
    }

    public int gibAnzahlChips(int schaleNr) {
        return schalen[schaleNr].gibAnzahlChips();
    }
}

import sas.*;
import java.awt.Color;
class Schale {

    private Rectangle grafik;
    private int anzahlInhalt;
    private int xPosition;
    private int yPosition;
    private int breite;
    private Circle[] inhalt = new Circle[15];

    public Schale(int pXPos, int pYPos, int pBreite, Color pFarbe) {
       grafik = new Rectangle(pXPos, pYPos, pBreite, pBreite, pFarbe);
       anzahlInhalt = 0;
       xPosition = pXPos;
       yPosition = pYPos;
       breite = pBreite;
       for (int i=0; i<15; i++) {
           inhalt[i] = null;
       }
    }

    public void inhaltHinzu(Circle chip) {
      inhalt[anzahlInhalt] = chip;
      anzahlInhalt = anzahlInhalt + 1;
      int zeile = (anzahlInhalt - 1) / 4;
      int spalte = (anzahlInhalt - 1) % 4;
      double differenz = (breite/5 - chip.getShapeWidth())/2;
      double xPos = differenz + spalte * breite / 5; 
      double yPos = differenz + zeile * breite / 5;
      double verschiebung = (breite - 4 * chip.getShapeWidth() - 3* differenz*2)/2;
      chip.moveTo(xPosition + verschiebung + xPos, yPosition + verschiebung + yPos);
    }    

    public void inhaltEntfernen(int anzahl) {
        if (anzahl <= anzahlInhalt) {
          for (int i = anzahlInhalt - anzahl; i<anzahlInhalt; i++) {
             inhalt[i].setHidden(true);
             inhalt[i]=null;
          }
          anzahlInhalt = anzahlInhalt - anzahl;
        }
    }

    public int gibAnzahlChips() {
        return anzahlInhalt;
    }

}

public class Spieler
{
    private Spielfeld spielfeld;  

    public Spieler(Spielfeld pSpielfeld)
    {
        spielfeld = pSpielfeld;
    }

    public void spielerZug()
    {
        boolean zugKorrekt = false;
        spielfeld.ziehen();
    }
}

import sasio.*;
import sas.*;
public class Computer
{

   private Spielfeld spielfeld; 
   private int[][] chipsBinaer = new int[5][4];


   public Computer(Spielfeld pSpielfeld)
   {
      spielfeld = pSpielfeld;
   }

   private int[] dezInBinaer(int zahl) {
      int[] binaerArray = new int [4];
      for (int i = 0; i < 4; i++) {
         binaerArray[i] = zahl % 2;
         zahl = zahl / 2;
      }
      return binaerArray;
   }

   public int binaerInDez(int[] binaerArray) {
      int zahl = 0;
      for (int i = 3; i >= 0; i--) {
         zahl = zahl * 2 + binaerArray[i];
      }
      return zahl;
   } 

   private int[] binaerSumme() {
      int[] binaerSumme = new int [4];
      for (int i = 0; i < 4; i++) {
         binaerSumme[i] = chipsBinaer[0][i];
      }
      for (int j = 1; j < 5; j++) {
         for (int i = 0; i < 4; i++) {
            binaerSumme[i] = (binaerSumme[i] + chipsBinaer[j][i]) % 2;
         }
      }
      return binaerSumme;
   }

   private void chipsBinaer() {
      for (int i = 0; i < 5; i++) {
         chipsBinaer[i] = dezInBinaer(spielfeld.gibAnzahlChips(i));
      }
   }

   private int[] berechneZug(int[] binaerSumme) {
      int schale = -1;
      int j = 0;
      int zug[] = new int[2];
      int[] summe = new int[4];
      int summeDezimal = 0;
      int chipsDezimal = 0;
      j = 0;
      while (schale == -1 && j < 5) {
         for (int i = 0; i < 4; i++) {
            summe[i] = (chipsBinaer[j][i] + binaerSumme[i]) % 2;
         }
         summeDezimal = binaerInDez(summe);
         chipsDezimal = spielfeld.gibAnzahlChips(j);
         if (summeDezimal < chipsDezimal) {
            schale = j;
         } else {
            if (j < 5) {
               j = j + 1;
            }
         }
      }

      if (schale == -1) {
         j = 0;
         while (spielfeld.gibAnzahlChips(j) == 0) {
            j = j + 1;
         }
         zug[0] = j;
         zug[1] = 1;
      } else {
         zug[0] = schale;
         zug [1] = spielfeld.gibAnzahlChips(schale) - summeDezimal;
      }
      return zug;
   }


   public void computerZug()
   {
      chipsBinaer(); 
      int[] binaerSumme = binaerSumme();
      int[] zug = new int[2];
      zug = berechneZug(binaerSumme);
      int schale = zug[0] + 1;
      Tools.message("Der Computer nimmt " + zug[1] + " Chips aus Schale " + schale, "Computerzug");
      spielfeld.nimmWeg(zug[0], zug[1]);

   }
}
